<?php use App\Core\Session; ?>
<div class="mb-4"><h1 class="h3 mb-1">Quản lý Merchant</h1><p class="text-muted mb-0">Approve / Reject / Lock hồ sơ Merchant. Khi approve, chủ shop được nâng role MERCHANT.</p></div>
<div class="row"><?php foreach($merchants as $m):?><div class="col-lg-6 mb-3"><div class="card shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between"><div><h2 class="h5 mb-1"><?= e((string)$m['name']) ?></h2><div class="small text-muted"><?= e((string)($m['owner_name']??'Chưa có chủ')) ?><?= !empty($m['owner_email'])?' · '.e((string)$m['owner_email']):'' ?></div></div><span class="badge badge-<?= e(match((string)$m['status']){'APPROVED'=>'success','PENDING'=>'warning','REJECTED'=>'danger','LOCKED'=>'dark',default=>'secondary'}) ?> align-self-start"><?= e(merchant_status_label((string)$m['status'])) ?></span></div><?php if(!empty($m['website_url'])):?><div class="mt-2"><a target="_blank" rel="noopener" href="<?= e((string)$m['website_url']) ?>"><?= e((string)$m['website_url']) ?></a></div><?php endif;?><?php if(!empty($m['review_note'])):?><div class="small text-muted mt-2">Ghi chú cũ: <?= e((string)$m['review_note']) ?></div><?php endif;?>
<?php if($m['owner_id']!==null):?><form method="post" action="<?= e(url('/admin/merchants/'.(int)$m['id'].'/review')) ?>" class="mt-3"><input type="hidden" name="_token" value="<?= e(Session::csrfToken()) ?>"><textarea class="form-control form-control-sm mb-2" name="note" rows="2" placeholder="Ghi chú kiểm duyệt..."></textarea><button class="btn btn-sm btn-success" name="action" value="APPROVE">Duyệt</button> <button class="btn btn-sm btn-outline-danger" name="action" value="REJECT">Từ chối</button> <button class="btn btn-sm btn-dark" name="action" value="LOCK">Khóa</button></form><?php endif;?></div></div></div><?php endforeach;?></div>
